// ======================================================
// 1) استقبال جميع السجلات
// ======================================================

const data = $input.all().map(item => item.json);

const num = (v) => Number(v) || 0;
const round = (v) => Math.round((v + Number.EPSILON) * 100) / 100;


// ======================================================
// 2) KPIs الأساسية
// ======================================================

const totalGrossSales = data.reduce(
  (sum, r) => sum + num(r.gross_sales), 0
);

const totalNetSales = data.reduce(
  (sum, r) => sum + num(r.net_sales), 0
);

// الخصومات الفعلية من العمود discount
const totalDiscount = data.reduce(
  (sum, r) => sum + num(r.discount), 0
);

// المرتجعات الفعلية من العمود return_amount
const totalReturns = data.reduce(
  (sum, r) => sum + num(r.return_amount), 0
);

// نسبة الخصومات من Gross Sales
const discountPercentage =
  totalGrossSales > 0
    ? (totalDiscount / totalGrossSales) * 100
    : 0;

// نسبة المرتجعات من Gross Sales
const returnPercentage =
  totalGrossSales > 0
    ? (totalReturns / totalGrossSales) * 100
    : 0;

// إجمالي الخصومات + المرتجعات
const totalDeductions =
  totalDiscount + totalReturns;

const deductionsPercentage =
  totalGrossSales > 0
    ? (totalDeductions / totalGrossSales) * 100
    : 0;


// ======================================================
// 3) الطلبات والعملاء
// ======================================================

const orders = new Set(
  data
    .map(r => r.order_id)
    .filter(v => v != null)
);

const customers = new Set(
  data
    .map(r => r.customer_id)
    .filter(v => v != null)
);

const averageOrderValue =
  orders.size > 0
    ? totalNetSales / orders.size
    : 0;

const averageSalesPerCustomer =
  customers.size > 0
    ? totalNetSales / customers.size
    : 0;


// ======================================================
// 4) تحليل المرتجعات العام
// ======================================================

// عدد البنود التي تحتوي على مرتجع
const returnedItemsRows = data.filter(
  r => num(r.return_amount) > 0
);

const returnedItemsCount =
  returnedItemsRows.length;

// عدد الطلبات التي تحتوي على مرتجع
const returnedOrders = new Set(
  returnedItemsRows
    .map(r => r.order_id)
    .filter(v => v != null)
);

const returnedOrdersCount =
  returnedOrders.size;

// نسبة الطلبات التي بها مرتجع
const returnedOrdersPercentage =
  orders.size > 0
    ? (returnedOrdersCount / orders.size) * 100
    : 0;


// ======================================================
// 5) دالة تجميع المبيعات
// ======================================================

function groupSales(field) {

  const result = {};

  for (const row of data) {

    const key =
      row[field] ?? "Unknown";

    if (!result[key]) {
      result[key] = 0;
    }

    result[key] +=
      num(row.net_sales);
  }

  return Object.entries(result)
    .map(([name, sales]) => ({

      name,

      sales:
        round(sales),

      contribution_percentage:
        totalNetSales > 0
          ? round(
              (sales / totalNetSales) * 100
            )
          : 0
    }))
    .sort(
      (a, b) =>
        b.sales - a.sales
    );
}


// ======================================================
// 6) التجميع الإجمالي
// ======================================================

const branchSales =
  groupSales("branch");

const productSales =
  groupSales("product_name");

const categorySales =
  groupSales("category");

const citySales =
  groupSales("city");

const channelSales =
  groupSales("sales_channel");


// ======================================================
// 7) دالة تحليل المرتجعات حسب بُعد
// ======================================================

function groupReturns(field) {

  const result = {};

  for (const row of data) {

    const key =
      row[field] ?? "Unknown";

    if (!result[key]) {

      result[key] = {
        return_amount: 0,
        gross_sales: 0,
        net_sales: 0,
        returned_orders: new Set()
      };
    }

    result[key].return_amount +=
      num(row.return_amount);

    result[key].gross_sales +=
      num(row.gross_sales);

    result[key].net_sales +=
      num(row.net_sales);

    if (
      num(row.return_amount) > 0 &&
      row.order_id != null
    ) {
      result[key].returned_orders.add(
        row.order_id
      );
    }
  }

  return Object.entries(result)
    .map(([name, values]) => ({

      name,

      return_amount:
        round(values.return_amount),

      return_percentage:
        values.gross_sales > 0
          ? round(
              (
                values.return_amount /
                values.gross_sales
              ) * 100
            )
          : 0,

      returned_orders_count:
        values.returned_orders.size,

      gross_sales:
        round(values.gross_sales),

      net_sales:
        round(values.net_sales)

    }))
    .sort(
      (a, b) =>
        b.return_amount -
        a.return_amount
    );
}


// ======================================================
// 8) المرتجعات حسب الأبعاد
// ======================================================

const returnsByBranch =
  groupReturns("branch");

const returnsByProduct =
  groupReturns("product_name");

const returnsByCategory =
  groupReturns("category");

const returnsByCity =
  groupReturns("city");

const returnsByChannel =
  groupReturns("sales_channel");


// ======================================================
// 9) المبيعات الشهرية
// ======================================================

const monthly = {};

for (const row of data) {

  if (!row.order_date) continue;

  const month =
    String(row.order_date).slice(0, 7);

  if (!monthly[month]) {

    monthly[month] = {

      gross_sales: 0,

      discount: 0,

      returns: 0,

      net_sales: 0,

      orders: new Set(),

      returned_orders: new Set()
    };
  }

  monthly[month].gross_sales +=
    num(row.gross_sales);

  monthly[month].discount +=
    num(row.discount);

  monthly[month].returns +=
    num(row.return_amount);

  monthly[month].net_sales +=
    num(row.net_sales);

  if (row.order_id != null) {

    monthly[month].orders.add(
      row.order_id
    );
  }

  if (
    num(row.return_amount) > 0 &&
    row.order_id != null
  ) {

    monthly[month].returned_orders.add(
      row.order_id
    );
  }
}


const monthlySales =
  Object.entries(monthly)
    .map(([month, values]) => ({

      month,

      gross_sales:
        round(values.gross_sales),

      discount:
        round(values.discount),

      discount_percentage:
        values.gross_sales > 0
          ? round(
              (
                values.discount /
                values.gross_sales
              ) * 100
            )
          : 0,

      returns:
        round(values.returns),

      return_percentage:
        values.gross_sales > 0
          ? round(
              (
                values.returns /
                values.gross_sales
              ) * 100
            )
          : 0,

      net_sales:
        round(values.net_sales),

      orders_count:
        values.orders.size,

      returned_orders_count:
        values.returned_orders.size,

      average_order_value:
        values.orders.size > 0
          ? round(
              values.net_sales /
              values.orders.size
            )
          : 0

    }))
    .sort(
      (a, b) =>
        a.month.localeCompare(b.month)
    );


// ======================================================
// 10) التجميع الشهري حسب بُعد
// ======================================================

function groupMonthlySales(field) {

  const result = {};

  for (const row of data) {

    if (!row.order_date) continue;

    const month =
      String(row.order_date)
        .slice(0, 7);

    const name =
      row[field] ?? "Unknown";

    if (!result[month]) {
      result[month] = {};
    }

    if (!result[month][name]) {
      result[month][name] = 0;
    }

    result[month][name] +=
      num(row.net_sales);
  }

  return Object.entries(result)
    .sort(
      ([monthA], [monthB]) =>
        monthA.localeCompare(monthB)
    )
    .map(([month, groups]) => ({

      month,

      items:
        Object.entries(groups)
          .map(([name, sales]) => ({

            name,

            sales:
              round(sales)

          }))
          .sort(
            (a, b) =>
              b.sales - a.sales
          )
    }));
}


// ======================================================
// 11) التجميع الشهري للمبيعات حسب الأبعاد
// ======================================================

const monthlySalesByBranch =
  groupMonthlySales("branch");

const monthlySalesByProduct =
  groupMonthlySales("product_name");

const monthlySalesByCategory =
  groupMonthlySales("category");

const monthlySalesByChannel =
  groupMonthlySales("sales_channel");


// ======================================================
// 12) مقارنة آخر شهرين للمبيعات
// ======================================================

function compareLatestMonths(monthlyGrouped) {

  if (monthlyGrouped.length < 2) {
    return [];
  }

  const current =
    monthlyGrouped[
      monthlyGrouped.length - 1
    ];

  const previous =
    monthlyGrouped[
      monthlyGrouped.length - 2
    ];

  const currentMap = {};
  const previousMap = {};

  for (const item of current.items) {
    currentMap[item.name] =
      item.sales;
  }

  for (const item of previous.items) {
    previousMap[item.name] =
      item.sales;
  }

  const allNames =
    new Set([
      ...Object.keys(currentMap),
      ...Object.keys(previousMap)
    ]);

  const comparison = [];

  for (const name of allNames) {

    const currentSales =
      num(currentMap[name]);

    const previousSales =
      num(previousMap[name]);

    const difference =
      currentSales -
      previousSales;

    const growthPercentage =
      previousSales !== 0
        ? (
            difference /
            previousSales
          ) * 100
        : null;

    comparison.push({

      name,

      previous_month:
        previous.month,

      previous_sales:
        round(previousSales),

      current_month:
        current.month,

      current_sales:
        round(currentSales),

      difference:
        round(difference),

      growth_percentage:
        growthPercentage === null
          ? null
          : round(growthPercentage),

      trend:
        difference > 0
          ? "Increase"
          : difference < 0
          ? "Decrease"
          : "No Change"
    });
  }

  return comparison.sort(
    (a, b) =>
      b.difference -
      a.difference
  );
}


const latestBranchComparison =
  compareLatestMonths(
    monthlySalesByBranch
  );

const latestProductComparison =
  compareLatestMonths(
    monthlySalesByProduct
  );

const latestCategoryComparison =
  compareLatestMonths(
    monthlySalesByCategory
  );

const latestChannelComparison =
  compareLatestMonths(
    monthlySalesByChannel
  );


// ======================================================
// 13) المرتجعات الشهرية حسب بُعد
// ======================================================

function groupMonthlyReturns(field) {

  const result = {};

  for (const row of data) {

    if (!row.order_date) continue;

    const month =
      String(row.order_date)
        .slice(0, 7);

    const name =
      row[field] ?? "Unknown";

    if (!result[month]) {
      result[month] = {};
    }

    if (!result[month][name]) {

      result[month][name] = {
        returns: 0,
        gross_sales: 0,
        returned_orders: new Set()
      };
    }

    result[month][name].returns +=
      num(row.return_amount);

    result[month][name].gross_sales +=
      num(row.gross_sales);

    if (
      num(row.return_amount) > 0 &&
      row.order_id != null
    ) {

      result[month][name]
        .returned_orders
        .add(row.order_id);
    }
  }

  return Object.entries(result)
    .sort(
      ([a], [b]) =>
        a.localeCompare(b)
    )
    .map(([month, groups]) => ({

      month,

      items:
        Object.entries(groups)
          .map(([name, values]) => ({

            name,

            return_amount:
              round(values.returns),

            return_percentage:
              values.gross_sales > 0
                ? round(
                    (
                      values.returns /
                      values.gross_sales
                    ) * 100
                  )
                : 0,

            returned_orders_count:
              values.returned_orders.size

          }))
          .sort(
            (a, b) =>
              b.return_amount -
              a.return_amount
          )
    }));
}


// ======================================================
// 14) المرتجعات الشهرية حسب الأبعاد
// ======================================================

const monthlyReturnsByBranch =
  groupMonthlyReturns("branch");

const monthlyReturnsByProduct =
  groupMonthlyReturns("product_name");

const monthlyReturnsByCategory =
  groupMonthlyReturns("category");

const monthlyReturnsByChannel =
  groupMonthlyReturns("sales_channel");


// ======================================================
// 15) مقارنة مرتجعات آخر شهرين
// ======================================================

function compareLatestReturns(monthlyGrouped) {

  if (monthlyGrouped.length < 2) {
    return [];
  }

  const current =
    monthlyGrouped[
      monthlyGrouped.length - 1
    ];

  const previous =
    monthlyGrouped[
      monthlyGrouped.length - 2
    ];

  const currentMap = {};
  const previousMap = {};

  for (const item of current.items) {
    currentMap[item.name] =
      item.return_amount;
  }

  for (const item of previous.items) {
    previousMap[item.name] =
      item.return_amount;
  }

  const allNames =
    new Set([
      ...Object.keys(currentMap),
      ...Object.keys(previousMap)
    ]);

  const result = [];

  for (const name of allNames) {

    const currentReturns =
      num(currentMap[name]);

    const previousReturns =
      num(previousMap[name]);

    const difference =
      currentReturns -
      previousReturns;

    const growthPercentage =
      previousReturns !== 0
        ? (
            difference /
            previousReturns
          ) * 100
        : null;

    result.push({

      name,

      previous_month:
        previous.month,

      previous_returns:
        round(previousReturns),

      current_month:
        current.month,

      current_returns:
        round(currentReturns),

      difference:
        round(difference),

      growth_percentage:
        growthPercentage === null
          ? null
          : round(growthPercentage),

      trend:
        difference > 0
          ? "Increase"
          : difference < 0
          ? "Decrease"
          : "No Change"
    });
  }

  return result.sort(
    (a, b) =>
      b.difference -
      a.difference
  );
}


const latestReturnBranchComparison =
  compareLatestReturns(
    monthlyReturnsByBranch
  );

const latestReturnProductComparison =
  compareLatestReturns(
    monthlyReturnsByProduct
  );

const latestReturnCategoryComparison =
  compareLatestReturns(
    monthlyReturnsByCategory
  );

const latestReturnChannelComparison =
  compareLatestReturns(
    monthlyReturnsByChannel
  );


// ======================================================
// 16) النمو الشهري الإجمالي MoM
// ======================================================

const monthlyGrowth =
  monthlySales.map(
    (current, index) => {

      if (index === 0) {

        return {

          month:
            current.month,

          net_sales:
            current.net_sales,

          previous_month_net_sales:
            null,

          difference:
            null,

          growth_percentage:
            null,

          trend:
            "No previous month"
        };
      }

      const previous =
        monthlySales[index - 1];

      const difference =
        current.net_sales -
        previous.net_sales;

      const growth =
        previous.net_sales !== 0
          ? (
              difference /
              previous.net_sales
            ) * 100
          : 0;

      return {

        month:
          current.month,

        net_sales:
          current.net_sales,

        previous_month_net_sales:
          previous.net_sales,

        difference:
          round(difference),

        growth_percentage:
          round(growth),

        trend:
          growth > 0
            ? "Increase"
            : growth < 0
            ? "Decrease"
            : "No Change"
      };
    }
  );


// ======================================================
// 17) أعلى وأقل شهر
// ======================================================

const monthsRanked =
  [...monthlySales].sort(
    (a, b) =>
      b.net_sales -
      a.net_sales
  );

const bestMonth =
  monthsRanked.length > 0
    ? monthsRanked[0]
    : null;

const worstMonth =
  monthsRanked.length > 0
    ? monthsRanked[
        monthsRanked.length - 1
      ]
    : null;


// ======================================================
// 18) Top 5
// ======================================================

const top5Products =
  productSales.slice(0, 5);

const top5Branches =
  branchSales.slice(0, 5);

const top5ReturnProducts =
  returnsByProduct
    .filter(
      x => x.return_amount > 0
    )
    .slice(0, 5);

const top5ReturnBranches =
  returnsByBranch
    .filter(
      x => x.return_amount > 0
    )
    .slice(0, 5);

const top5ReturnCategories =
  returnsByCategory
    .filter(
      x => x.return_amount > 0
    )
    .slice(0, 5);


// ======================================================
// 19) أحدث نمو شهري
// ======================================================

const latestMonthlyGrowth =
  monthlyGrowth.length > 1
    ? monthlyGrowth[
        monthlyGrowth.length - 1
      ]
    : null;


// ======================================================
// 20) نطاق البيانات
// ======================================================

const availableMonths =
  monthlySales.map(
    m => m.month
  );

const firstAvailableMonth =
  availableMonths.length > 0
    ? availableMonths[0]
    : null;

const latestAvailableMonth =
  availableMonths.length > 0
    ? availableMonths[
        availableMonths.length - 1
      ]
    : null;


// ======================================================
// 21) تحليل العملاء
// ======================================================

const customerSalesMap = {};

for (const row of data) {

  if (row.customer_id == null) {
    continue;
  }

  const customerId =
    String(row.customer_id);

  if (!customerSalesMap[customerId]) {

    customerSalesMap[customerId] = {

      customer_id:
        customerId,

      net_sales:
        0,

      returns:
        0,

      orders:
        new Set()
    };
  }

  customerSalesMap[
    customerId
  ].net_sales +=
    num(row.net_sales);

  customerSalesMap[
    customerId
  ].returns +=
    num(row.return_amount);

  if (row.order_id != null) {

    customerSalesMap[
      customerId
    ].orders.add(
      row.order_id
    );
  }
}


const customerSales =
  Object.values(
    customerSalesMap
  )
    .map(customer => ({

      customer_id:
        customer.customer_id,

      net_sales:
        round(
          customer.net_sales
        ),

      returns:
        round(
          customer.returns
        ),

      orders_count:
        customer.orders.size,

      average_order_value:
        customer.orders.size > 0
          ? round(
              customer.net_sales /
              customer.orders.size
            )
          : 0,

      contribution_percentage:
        totalNetSales > 0
          ? round(
              (
                customer.net_sales /
                totalNetSales
              ) * 100
            )
          : 0

    }))
    .sort(
      (a, b) =>
        b.net_sales -
        a.net_sales
    );


const top5Customers =
  customerSales.slice(0, 5);


// ======================================================
// 22) المبيعات الأسبوعية
// الأسبوع يبدأ يوم الاثنين
// ======================================================

const weekly = {};

function getWeekStart(dateValue) {

  const date =
    new Date(
      `${dateValue}T00:00:00Z`
    );

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return null;
  }

  const day =
    date.getUTCDay();

  const diffToMonday =
    day === 0
      ? -6
      : 1 - day;

  date.setUTCDate(
    date.getUTCDate() +
    diffToMonday
  );

  return date
    .toISOString()
    .slice(0, 10);
}


for (const row of data) {

  if (!row.order_date) continue;

  const weekStart =
    getWeekStart(
      row.order_date
    );

  if (!weekStart) continue;

  if (!weekly[weekStart]) {

    weekly[weekStart] = {

      gross_sales: 0,

      discount: 0,

      returns: 0,

      net_sales: 0,

      orders: new Set(),

      returned_orders:
        new Set()
    };
  }

  weekly[weekStart]
    .gross_sales +=
    num(row.gross_sales);

  weekly[weekStart]
    .discount +=
    num(row.discount);

  weekly[weekStart]
    .returns +=
    num(row.return_amount);

  weekly[weekStart]
    .net_sales +=
    num(row.net_sales);

  if (row.order_id != null) {

    weekly[weekStart]
      .orders
      .add(row.order_id);
  }

  if (
    num(row.return_amount) > 0 &&
    row.order_id != null
  ) {

    weekly[weekStart]
      .returned_orders
      .add(row.order_id);
  }
}


const weeklySales =
  Object.entries(weekly)
    .map(
      ([weekStart, values]) => ({

        week_start:
          weekStart,

        gross_sales:
          round(
            values.gross_sales
          ),

        discount:
          round(
            values.discount
          ),

        returns:
          round(
            values.returns
          ),

        net_sales:
          round(
            values.net_sales
          ),

        orders_count:
          values.orders.size,

        returned_orders_count:
          values
            .returned_orders
            .size,

        average_order_value:
          values.orders.size > 0
            ? round(
                values.net_sales /
                values.orders.size
              )
            : 0

      })
    )
    .sort(
      (a, b) =>
        a.week_start.localeCompare(
          b.week_start
        )
    );


// ======================================================
// 23) فحص صحة المعادلات
// ======================================================

// لأن sales_analytics تجعل net_sales = 0 للطلبات الملغاة،
// يجب استبعاد كامل Gross Sales الخاص بها من الصافي المتوقع.
// كذلك لا نخصم discount/return_amount للطلبات الملغاة مرة ثانية.
const totalCancelledGrossSales = data
  .filter(
    r => String(r.status || "").toLowerCase() === "cancelled"
  )
  .reduce(
    (sum, r) => sum + num(r.gross_sales),
    0
  );

const validDiscounts = data
  .filter(
    r => String(r.status || "").toLowerCase() !== "cancelled"
  )
  .reduce(
    (sum, r) => sum + num(r.discount),
    0
  );

const validReturns = data
  .filter(
    r => String(r.status || "").toLowerCase() !== "cancelled"
  )
  .reduce(
    (sum, r) => sum + num(r.return_amount),
    0
  );

const expectedNetSales =
  totalGrossSales -
  totalCancelledGrossSales -
  validDiscounts -
  validReturns;

const reconciliationDifference =
  round(expectedNetSales - totalNetSales);

const reconciliationStatus =
  Math.abs(reconciliationDifference) < 0.01
    ? "OK"
    : "CHECK DATA";


// ======================================================
// 24) النتيجة النهائية
// ======================================================

return [
  {
    json: {

      // --------------------------------
      // نطاق البيانات
      // --------------------------------

      first_available_month:
        firstAvailableMonth,

      latest_available_month:
        latestAvailableMonth,

      available_months:
        availableMonths,


      // --------------------------------
      // KPIs الأساسية
      // --------------------------------

      total_gross_sales:
        round(totalGrossSales),

      total_discount:
        round(totalDiscount),

      discount_percentage:
        round(discountPercentage),

      total_returns:
        round(totalReturns),

      return_percentage:
        round(returnPercentage),

      total_deductions:
        round(totalDeductions),

      deductions_percentage:
