const rows = $input.all().map(item => item.json);

// ---------- Helpers ----------
const num = (v) => Number(v) || 0;

const money = (v) =>
  Math.round((v + Number.EPSILON) * 100) / 100;

// ---------- Basic KPIs ----------
const grossSales = rows.reduce((s, r) => s + num(r.gross_sales), 0);
const netSales = rows.reduce((s, r) => s + num(r.net_sales), 0);
const totalDiscount = rows.reduce((s, r) => s + num(r.discount), 0);
const totalReturns = rows.reduce((s, r) => s + num(r.return_amount), 0);
const totalQuantity = rows.reduce((s, r) => s + num(r.quantity), 0);

const orders = new Set(rows.map(r => r.order_id)).size;
const customers = new Set(rows.map(r => r.customer_id)).size;

const aov = orders ? netSales / orders : 0;
const discountRate = grossSales ? (totalDiscount / grossSales) * 100 : 0;

// ---------- Branch Analysis ----------
const branchSales = {};

for (const r of rows) {
  const branch = r.branch || 'Unknown';

  if (!branchSales[branch]) {
    branchSales[branch] = 0;
  }

  branchSales[branch] += num(r.net_sales);
}

const branches = Object.entries(branchSales)
  .map(([branch, sales]) => ({
    branch,
    net_sales: money(sales),
    share_percent: netSales
      ? money((sales / netSales) * 100)
      : 0
  }))
  .sort((a, b) => b.net_sales - a.net_sales);

const topBranch = branches[0] || null;

// ---------- Product Analysis ----------
const productSales = {};

for (const r of rows) {
  const product = r.product_name || 'Unknown';

  if (!productSales[product]) {
    productSales[product] = 0;
  }

  productSales[product] += num(r.net_sales);
}

const products = Object.entries(productSales)
  .map(([product, sales]) => ({
    product,
    net_sales: money(sales),
    share_percent: netSales
      ? money((sales / netSales) * 100)
      : 0
  }))
  .sort((a, b) => b.net_sales - a.net_sales);

const topProduct = products[0] || null;

// ---------- Monthly Analysis ----------
const monthlySales = {};

for (const r of rows) {
  if (!r.order_date) continue;

  const month = String(r.order_date).slice(0, 7);

  if (!monthlySales[month]) {
    monthlySales[month] = 0;
  }

  monthlySales[month] += num(r.net_sales);
}

const months = Object.entries(monthlySales)
  .map(([month, sales]) => ({
    month,
    net_sales: money(sales)
  }))
  .sort((a, b) => a.month.localeCompare(b.month));

const bestMonth =
  [...months].sort((a, b) => b.net_sales - a.net_sales)[0] || null;

// ---------- Sales Channel Analysis ----------
const channelSales = {};

for (const r of rows) {
  const channel = r.sales_channel || 'Unknown';

  if (!channelSales[channel]) {
    channelSales[channel] = 0;
  }

  channelSales[channel] += num(r.net_sales);
}

const channels = Object.entries(channelSales)
  .map(([channel, sales]) => ({
    channel,
    net_sales: money(sales),
    share_percent: netSales
      ? money((sales / netSales) * 100)
      : 0
  }))
  .sort((a, b) => b.net_sales - a.net_sales);

// ---------- Return one clean object ----------
return [
  {
    json: {
      kpis: {
        gross_sales: money(grossSales),
        net_sales: money(netSales),
        total_discount: money(totalDiscount),
        discount_rate: money(discountRate),
        total_returns: money(totalReturns),
        total_quantity: totalQuantity,
        orders,
        customers,
        average_order_value: money(aov)
      },

      top_branch: topBranch,
      branches,

      top_product: topProduct,
      top_products: products.slice(0, 10),

      best_month: bestMonth,
      monthly_sales: months,

      sales_channels: channels,

      data_period: {
        from: months.length ? months[0].month : null,
        to: months.length ? months[months.length - 1].month : null
      }
    }
  }
];
